<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('payments.view');
$pageTitle='Ingresos registrados';$pdo=db();$q=trim((string)($_GET['q']??''));$currency=(string)($_GET['currency']??'');$month=(string)($_GET['month']??'');$clientId=max(0,(int)($_GET['client_id']??0));$clients=$pdo->query("SELECT id,company_name,country FROM clients ORDER BY COALESCE(NULLIF(country,''),'Sin país'),company_name")->fetchAll();$where=[];$params=[];
if($clientId){$where[]='p.client_id=?';$params[]=$clientId;}if($q!==''){$where[]='(c.company_name LIKE ? OR p.reference LIKE ? OR p.payment_method LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if(in_array($currency,['CLP','USD','BRL'],true)){$where[]='p.currency=?';$params[]=$currency;}if(preg_match('/^\d{4}-\d{2}$/',$month)){$where[]="DATE_FORMAT(p.payment_date,'%Y-%m')=?";$params[]=$month;}
$sql='SELECT p.*,c.company_name,s.name service_name,q.quotation_number,u.name creator_name FROM payments p JOIN clients c ON c.id=p.client_id LEFT JOIN client_services s ON s.id=p.service_id LEFT JOIN quotations q ON q.id=p.quotation_id LEFT JOIN users u ON u.id=p.created_by'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.payment_date DESC,p.id DESC';$stmt=$pdo->prepare($sql);$stmt->execute($params);$payments=$stmt->fetchAll();
$totals=['CLP'=>0.0,'USD'=>0.0,'BRL'=>0.0];foreach($payments as$p)$totals[$p['currency']]=(float)$totals[$p['currency']]+(float)$p['amount'];
require __DIR__.'/includes/header.php';
?>
<div class="stats-grid"><?php foreach($totals as$cur=>$total):?><div class="stat-card" style="--accent:<?=$cur==='CLP'?'#0074c7':($cur==='USD'?'#73bc25':'#ff5300')?>"><small>TOTAL <?=e($cur)?></small><strong style="font-size:25px"><?=e(format_money($total,$cur))?></strong><span>Según los filtros actuales</span></div><?php endforeach;?></div>
<section class="panel"><div class="panel-header"><div><h2>Historial de ingresos</h2><span class="table-sub"><?=count($payments)?> registros. Estos datos alimentan el gráfico mensual del dashboard.</span></div><?php if(has_permission('payments.manage')):?><a class="btn btn-primary" href="payment_form.php">+ REGISTRAR INGRESO</a><?php endif;?></div><div class="panel-body"><form method="get" class="filters"><select name="client_id"><option value="0">Todos los clientes</option><?php foreach($clients as$c):?><option value="<?=(int)$c['id']?>" <?=$clientId===(int)$c['id']?'selected':''?>><?=e(($c['country']?:'Sin país').' · '.$c['company_name'])?></option><?php endforeach;?></select><input name="q" value="<?=e($q)?>" placeholder="Referencia o método"><select name="currency"><option value="">Todas las monedas</option><option value="CLP" <?=$currency==='CLP'?'selected':''?>>CLP</option><option value="USD" <?=$currency==='USD'?'selected':''?>>USD</option><option value="BRL" <?=$currency==='BRL'?'selected':''?>>BRL</option></select><input type="month" name="month" value="<?=e($month)?>"><button class="btn btn-secondary btn-small">Filtrar</button></form></div><div class="table-wrap"><?php if(!$payments):?><div class="empty">Todavía no hay ingresos registrados.</div><?php else:?><table class="data-table"><thead><tr><th>Fecha / cliente</th><th>Origen</th><th>Método</th><th>Referencia</th><th>Moneda</th><th>Valor</th><th></th></tr></thead><tbody><?php foreach($payments as$p):?><tr><td><strong><?=e(format_date($p['payment_date']))?></strong><span class="table-sub"><?=e($p['company_name'])?></span></td><td><?=e($p['service_name']?:$p['quotation_number']?:'Ingreso general')?></td><td><?=e($p['payment_method']?:'—')?></td><td><?=e($p['reference']?:'—')?></td><td><?=e($p['currency'])?></td><td><strong><?=e(format_money($p['amount'],$p['currency']))?></strong></td><td><?php if(has_permission('payments.manage')):?><a class="btn btn-light btn-small" href="payment_form.php?id=<?=(int)$p['id']?>">Editar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
